class EventSource {
    private final List<Runnable> listeners = new ArrayList<>();
    void addListener(Runnable l) { listeners.add(l); } // strong reference held forever
    void fire() { listeners.forEach(Runnable::run); }
}

var source = new EventSource(); // long-lived (e.g. a singleton bean)
for (int i = 0; i < 1000; i++) {
    var controller = new UIController();
    source.addListener(controller::refresh); // registers, never detaches
    // controller goes out of scope but CANNOT be GC'd: source still references it
}
// 1000 dead controllers stuck in memory -> a slow, growing leak.
```

```java
class EventSource {
    private final List<Runnable> listeners = new CopyOnWriteArrayList<>();
    void addListener(Runnable l) { listeners.add(l); }
    void removeListener(Runnable l) { listeners.remove(l); } // the missing half
    void fire() { listeners.forEach(Runnable::run); }
}

var source = new EventSource();
Runnable obs = () -> System.out.println("refresh");
source.addListener(obs);
// ...when the observer's lifecycle ends:
source.removeListener(obs);   // now it can be garbage collected

// Alternative: store observers in a WeakReference / WeakHashMap so the GC
// can reclaim them automatically once nothing else references them.
```

