class OrderSubject {
    private final List<Observer> observers = new CopyOnWriteArrayList<>(); // safe iteration
    private final AtomicReference<OrderStatus> status =
        new AtomicReference<>(OrderStatus.PENDING);

    void attach(Observer o) { observers.add(o); }   // thread-safe
    void detach(Observer o) { observers.remove(o); } // thread-safe

    void updateStatus(OrderStatus next) {
        var prev = status.getAndSet(next);           // atomic state change
        if (prev != next) {
            for (Observer o : observers) o.update(next); // iterates a stable snapshot
        }
    }
    OrderStatus current() { return status.get(); }   // lock-free read
}

interface Observer { void update(OrderStatus s); }
enum OrderStatus { PENDING, CONFIRMED, SHIPPED }
```

*Reads never block; a concurrent `attach` just appears in the next notification cycle.*

