interface CartObserver { void onCartUpdated(Cart cart); }

class Cart {
    private final List<CartObserver> observers = new CopyOnWriteArrayList<>();
    private final List<CartItem> items = new ArrayList<>();

    void addObserver(CartObserver o) { observers.add(o); }
    void removeObserver(CartObserver o) { observers.remove(o); } // prevents leaks

    void addItem(CartItem item) {
        items.add(item);
        observers.forEach(o -> o.onCartUpdated(this)); // notify, don't name names
    }
    List<CartItem> getItems() { return List.copyOf(items); }
}

class InventoryService implements CartObserver {
    public void onCartUpdated(Cart c) { System.out.println("Reserve " + c.getItems().size()); }
}
class AnalyticsService implements CartObserver {
    public void onCartUpdated(Cart c) { System.out.println("Track update"); }
}
// Add a recommendation observer later -> Cart never changes.
```

*The `Cart` depends on one interface, not three concrete services — that's the decoupling.*

