interface Observer { void update(Cart source); } // source = the subject

class Cart {
    private final List<Observer> observers = new CopyOnWriteArrayList<>();
    private int version;
    int getVersion() { return version; }
    List<CartItem> getItems() { return List.copyOf(items); }
    private final List<CartItem> items = new ArrayList<>();

    void addItem(CartItem item) {
        items.add(item); version++;
        observers.forEach(o -> o.update(this)); // just a signal + reference
    }
}

class CountLogger implements Observer {
    public void update(Cart c) { System.out.println(c.getItems().size()); } // pulls only count
}
class CacheInvalidator implements Observer {
    public void update(Cart c) { System.out.println("evict v" + c.getVersion()); } // pulls version
}
