@Service
class CartService {
    private final ApplicationEventPublisher publisher; // subject
    private final CartRepository repo;
    CartService(ApplicationEventPublisher publisher, CartRepository repo) {
        this.publisher = publisher; this.repo = repo;
    }

    @Transactional
    public void checkout(Long cartId) {
        var cart = repo.findById(cartId).orElseThrow();
        cart.setStatus(CartStatus.CHECKED_OUT);
        repo.save(cart);
        publisher.publishEvent(new CartCheckedOut(cart.getId())); // notify observers
    }
}

record CartCheckedOut(Long cartId) {} // the data carried to observers

@Component
class PaymentListener {                 // observer (runs in publisher's thread)
    @EventListener
    void onCheckout(CartCheckedOut e) { System.out.println("Pay for " + e.cartId()); }
}

@Component
class InventoryListener {               // observer (runs only after commit)
    @TransactionalEventListener(phase = TransactionPhase.AFTER_COMMIT)
    void onCheckout(CartCheckedOut e) { System.out.println("Reserve for " + e.cartId()); }
}
